enum EngineStatus: String, Sendable {
    case stopped
    case starting
    case running
    case error

    var color: Color {
        switch self {
        case .stopped:  return Color(hex: "#EF4444")
        case .starting: return Color(hex: "#F59E0B")
        case .running:  return Color(hex: "#10B981")
        case .error:    return Color(hex: "#F97316")
        }
    }

    var displayName: String {
        switch self {
        case .stopped:  return "Stopped"
        case .starting: return "Starting..."
        case .running:  return "Running"
        case .error:    return "Error"
        }
    }

    var systemImage: String {
        switch self {
        case .stopped:  return "stop.circle.fill"
        case .starting: return "hourglass.circle.fill"
        case .running:  return "checkmark.circle.fill"
        case .error:    return "exclamationmark.circle.fill"
        }
    }
}

