        switch self {
        case .rhythm: return 8
        case .bass:   return 4
        case .melody: return 4
        case .fx:     return 4
        }
    }

    var gridColumns: Int { 4 }

    var gridRows: Int {
        switch self {
        case .rhythm: return 2
        default: return 1
        }
    }
}

