import Foundation

struct Channel: Identifiable, Equatable, Sendable {
    let id: Int
    var volume: Double
    var isMuted: Bool
    var isSolo: Bool
    var eqLow: Double
    var eqMid: Double
    var eqHigh: Double
    var activeSnippetId: UUID?

    init(
        id: Int,
        volume: Double = 0.8,
        isMuted: Bool = false,
        isSolo: Bool = false,
        eqLow: Double = 0.0,
        eqMid: Double = 0.0,
        eqHigh: Double = 0.0,
        activeSnippetId: UUID? = nil
    ) {
        self.id = id
        self.volume = volume
        self.isMuted = isMuted
        self.isSolo = isSolo
        self.eqLow = eqLow
        self.eqMid = eqMid
        self.eqHigh = eqHigh
        self.activeSnippetId = activeSnippetId
    }

    var orbitName: String { "d\(id)" }

    var dbValue: Double {
        if volume <= 0 {
            return -Double.infinity
        }
        return 20 * log10(volume)
    }

    var dbString: String {
        if volume <= 0 {
            return "-∞ dB"
        }
        let db = dbValue
        return String(format: "%.1f dB", db)
    }

    var isActive: Bool {
        activeSnippetId != nil && !isMuted
    }

    var effectiveVolume: Double {
        isMuted ? 0.0 : volume
    }
}

extension Channel {
    static func createChannels() -> [Channel] {
        (1...8).map { Channel(id: $0) }
    }
}

