import Foundation

struct Session: Identifiable, Codable, Equatable, Sendable {
    let id: UUID
    var name: String
    var bpm: Double
    var snippetAssignments: [String: UUID]
    var createdAt: Date
    var updatedAt: Date

    init(
        id: UUID = UUID(),
        name: String = "New Session",
        bpm: Double = 120.0,
        snippetAssignments: [String: UUID] = [:],
        createdAt: Date = Date(),
        updatedAt: Date = Date()
    ) {
        self.id = id
        self.name = name
        self.bpm = bpm
        self.snippetAssignments = snippetAssignments
        self.createdAt = createdAt
        self.updatedAt = updatedAt
    }

    func withUpdatedTimestamp() -> Session {
        Session(
            id: id,
            name: name,
            bpm: bpm,
            snippetAssignments: snippetAssignments,
            createdAt: createdAt,
            updatedAt: Date()
        )
    }

    func withBpm(_ newBpm: Double) -> Session {
        Session(
            id: id,
            name: name,
            bpm: newBpm,
            snippetAssignments: snippetAssignments,
            createdAt: createdAt,
            updatedAt: Date()
        )
    }

    func withSnippetAssignment(position: String, snippetId: UUID?) -> Session {
        var newAssignments = snippetAssignments
        if let snippetId = snippetId {
            newAssignments[position] = snippetId
        } else {
            newAssignments.removeValue(forKey: position)
        }
        return Session(
            id: id,
            name: name,
            bpm: bpm,
            snippetAssignments: newAssignments,
            createdAt: createdAt,
            updatedAt: Date()
        )
    }
}

