enum LogSource: String, Sendable {
    case superCollider
    case tidal
    case app

    var color: Color {
        switch self {
        case .superCollider: return Color(hex: "#4ECDC4")
        case .tidal:         return Color(hex: "#A78BFA")
        case .app:           return Color(hex: "#8888AA")
        }
    }

    var label: String {
        switch self {
        case .superCollider: return "SC"
        case .tidal:         return "Tidal"
        case .app:           return "App"
        }
    }
}

enum LogLevel: String, Sendable {
    case info
    case warning
    case error

    var color: Color {
        switch self {
        case .info:    return Color(hex: "#E8E8F0")
        case .warning: return Color(hex: "#F59E0B")
        case .error:   return Color(hex: "#EF4444")
        }
    }
}

struct LogEntry: Identifiable, Sendable {
    let id: UUID
    let timestamp: Date
    let source: LogSource
    let level: LogLevel
    let message: String

    init(
        id: UUID = UUID(),
        timestamp: Date = Date(),
        source: LogSource,
        level: LogLevel = .info,
        message: String
    ) {
        self.id = id
        self.timestamp = timestamp
        self.source = source
        self.level = level
        self.message = message
    }
}

extension LogEntry {
    static func detect(text: String, source: LogSource) -> LogLevel {
        let lowercased = text.lowercased()
        if lowercased.contains("error") || lowercased.contains("exception") || lowercased.contains("failed") {
            return .error
        } else if lowercased.contains("warning") || lowercased.contains("warn") {
            return .warning
        }
        return .info
    }
}

