import Foundation

actor SnippetStore {
    private var snippets: [Snippet] = []
    private let fileManager = FileManager.default

    private var userSnippetsURL: URL {
        let appSupport = fileManager.urls(for: .applicationSupportDirectory, in: .userDomainMask).first!
        let appDir = appSupport.appendingPathComponent("TidalPadController", isDirectory: true)

        if !fileManager.fileExists(atPath: appDir.path) {
            try? fileManager.createDirectory(at: appDir, withIntermediateDirectories: true)
        }

        return appDir.appendingPathComponent("user-snippets.json")
    }

    func loadSnippets() async throws -> [Snippet] {
        var allSnippets: [Snippet] = []

        if let bundleURL = Bundle.main.url(forResource: "default-snippets", withExtension: "json") {
            let bundleSnippets = try loadSnippets(from: bundleURL)
            allSnippets.append(contentsOf: bundleSnippets)
        }

        if fileManager.fileExists(atPath: userSnippetsURL.path) {
            let userSnippets = try loadSnippets(from: userSnippetsURL)
            allSnippets.append(contentsOf: userSnippets)
        }

        snippets = allSnippets
        return allSnippets
    }

    private func loadSnippets(from url: URL) throws -> [Snippet] {
        let data = try Data(contentsOf: url)
        let decoder = JSONDecoder()
        return try decoder.decode([Snippet].self, from: data)
    }

    func saveUserSnippets(_ userSnippets: [Snippet]) async throws {
        let encoder = JSONEncoder()
        encoder.outputFormatting = [.prettyPrinted, .sortedKeys]
        let data = try encoder.encode(userSnippets)
        try data.write(to: userSnippetsURL)
    }

    func snippet(by id: UUID) -> Snippet? {
        snippets.first { $0.id == id }
    }

    func snippets(for category: SnippetCategory) -> [Snippet] {
        snippets.filter { $0.category == category }
    }

    func snippets(for orbit: String) -> [Snippet] {
        snippets.filter { $0.orbit == orbit }
    }

    func allSnippets() -> [Snippet] {
        snippets
    }

    func addSnippet(_ snippet: Snippet) async throws {
        snippets.append(snippet)
        let userSnippets = snippets.filter { snippet in
            if let bundleURL = Bundle.main.url(forResource: "default-snippets", withExtension: "json"),
               let bundleData = try? Data(contentsOf: bundleURL),
               let bundleSnippets = try? JSONDecoder().decode([Snippet].self, from: bundleData) {
                return !bundleSnippets.contains { $0.id == snippet.id }
            }
            return true
        }
        try await saveUserSnippets(userSnippets)
    }

    func updateSnippet(_ snippet: Snippet) async throws {
        if let index = snippets.firstIndex(where: { $0.id == snippet.id }) {
            snippets[index] = snippet
            let userSnippets = snippets.filter { snippet in
                if let bundleURL = Bundle.main.url(forResource: "default-snippets", withExtension: "json"),
                   let bundleData = try? Data(contentsOf: bundleURL),
                   let bundleSnippets = try? JSONDecoder().decode([Snippet].self, from: bundleData) {
                    return !bundleSnippets.contains { $0.id == snippet.id }
                }
                return true
            }
            try await saveUserSnippets(userSnippets)
        }
    }

    func deleteSnippet(_ id: UUID) async throws {
        snippets.removeAll { $0.id == id }
        let userSnippets = snippets.filter { snippet in
            if let bundleURL = Bundle.main.url(forResource: "default-snippets", withExtension: "json"),
               let bundleData = try? Data(contentsOf: bundleURL),
               let bundleSnippets = try? JSONDecoder().decode([Snippet].self, from: bundleData) {
                return !bundleSnippets.contains { $0.id == snippet.id }
            }
            return true
        }
        try await saveUserSnippets(userSnippets)
    }
}

