import Foundation
import Observation
import SwiftUI

@Observable
@MainActor
final class AppState {
    // MARK: - Services

    let engineManager: EngineManager
    private let snippetStore: SnippetStore

    // MARK: - State

    private(set) var snippets: [Snippet] = []
    private(set) var channels: [Channel] = Channel.createChannels()
    private(set) var activePatterns: [String: Snippet] = [:]
    private(set) var logEntries: [LogEntry] = []

    var bpm: Double = 120.0 {
        didSet {
            if oldValue != bpm {
                updateTempo(bpm)
            }
        }
    }

    var masterVolume: Double = 1.0

    var autoScroll: Bool = true

    // MARK: - Tap Tempo

    private var tapTimestamps: [Date] = []

    // MARK: - Initialization

    init() {
        self.engineManager = EngineManager()
        self.snippetStore = SnippetStore()

        engineManager.onLogEntry = { [weak self] entry in
            Task { @MainActor [weak self] in
                self?.logEntries.append(entry)
                if let count = self?.logEntries.count, count > 1000 {
                    self?.logEntries.removeFirst(count - 1000)
                }
            }
        }
    }

    // MARK: - Snippet Loading

    func loadSnippets() async {
        do {
            snippets = try await snippetStore.loadSnippets()
        } catch {
            appendAppLog("Failed to load snippets: \(error.localizedDescription)", level: .error)
        }
    }

    func snippets(for category: SnippetCategory) -> [Snippet] {
        snippets.filter { $0.category == category }
    }

    // MARK: - Pad Actions

    func togglePad(snippet: Snippet) {
        let orbit = snippet.orbit

        if activePatterns[orbit]?.id == snippet.id {
            silenceOrbit(orbit)
        } else {
            playSnippet(snippet)
        }
    }

    func playSnippet(_ snippet: Snippet) {
        let orbit = snippet.orbit
        let channelIndex = extractChannelIndex(from: orbit)

        guard let index = channelIndex, index >= 0 && index < channels.count else {
            appendAppLog("Invalid orbit: \(orbit)", level: .error)
            return
        }

        let effectiveGain = channels[index].effectiveVolume * masterVolume
        let code = snippet.codeWithGain(effectiveGain)

        engineManager.sendToTidal(code)
        activePatterns[orbit] = snippet

        channels[index] = Channel(
            id: channels[index].id,
            volume: channels[index].volume,
            isMuted: channels[index].isMuted,
            isSolo: channels[index].isSolo,
            eqLow: channels[index].eqLow,
            eqMid: channels[index].eqMid,
            eqHigh: channels[index].eqHigh,
            activeSnippetId: snippet.id
        )

        appendAppLog("Playing \(snippet.name) on \(orbit)")
    }

    func silenceOrbit(_ orbit: String) {
        engineManager.sendToTidal("\(orbit) $ silence")
        activePatterns.removeValue(forKey: orbit)

        if let channelIndex = extractChannelIndex(from: orbit),
           channelIndex >= 0 && channelIndex < channels.count {
            channels[channelIndex] = Channel(
                id: channels[channelIndex].id,
                volume: channels[channelIndex].volume,
                isMuted: channels[channelIndex].isMuted,
                isSolo: channels[channelIndex].isSolo,
                eqLow: channels[channelIndex].eqLow,
                eqMid: channels[channelIndex].eqMid,
                eqHigh: channels[channelIndex].eqHigh,
                activeSnippetId: nil
            )
        }

        appendAppLog("Silenced \(orbit)")
    }

    func isActive(snippet: Snippet) -> Bool {
        activePatterns[snippet.orbit]?.id == snippet.id
    }

    // MARK: - Tempo

    func updateTempo(_ newBpm: Double) {
        let cps = newBpm / 60.0 / 4.0
        engineManager.sendToTidal("setcps \(cps)")
        appendAppLog("BPM set to \(Int(newBpm)) (cps: \(String(format: "%.4f", cps)))")
    }

    func tapTempo() {
        let now = Date()
        tapTimestamps.append(now)

        tapTimestamps = tapTimestamps.filter { now.timeIntervalSince($0) < 3.0 }

        if tapTimestamps.count >= 2 {
            let intervals = zip(tapTimestamps.dropFirst(), tapTimestamps).map { $0.timeIntervalSince($1) }
            let avgInterval = intervals.reduce(0, +) / Double(intervals.count)
            let calculatedBpm = 60.0 / avgInterval

            if calculatedBpm >= 40 && calculatedBpm <= 300 {
                bpm = round(calculatedBpm * 10) / 10
            }
        }
    }

    // MARK: - Mixer

    func updateChannelVolume(_ channelId: Int, volume: Double) {
        guard channelId >= 1 && channelId <= channels.count else { return }
        let index = channelId - 1

        channels[index] = Channel(
            id: channels[index].id,
            volume: volume,
            isMuted: channels[index].isMuted,
            isSolo: channels[index].isSolo,
            eqLow: channels[index].eqLow,
            eqMid: channels[index].eqMid,
            eqHigh: channels[index].eqHigh,
            activeSnippetId: channels[index].activeSnippetId
        )

        resendPatternForChannel(channelId)
    }

    func toggleMute(_ channelId: Int) {
        guard channelId >= 1 && channelId <= channels.count else { return }
        let index = channelId - 1
        let newMuted = !channels[index].isMuted

        channels[index] = Channel(
            id: channels[index].id,
            volume: channels[index].volume,
            isMuted: newMuted,
            isSolo: channels[index].isSolo,
            eqLow: channels[index].eqLow,
            eqMid: channels[index].eqMid,
            eqHigh: channels[index].eqHigh,
            activeSnippetId: channels[index].activeSnippetId
        )

        if newMuted {
            engineManager.sendToTidal("d\(channelId) $ silence")
        } else {
            resendPatternForChannel(channelId)
        }
    }

    func toggleSolo(_ channelId: Int) {
        guard channelId >= 1 && channelId <= channels.count else { return }
        let index = channelId - 1
        let newSolo = !channels[index].isSolo

        channels[index] = Channel(
            id: channels[index].id,
            volume: channels[index].volume,
            isMuted: channels[index].isMuted,
            isSolo: newSolo,
            eqLow: channels[index].eqLow,
            eqMid: channels[index].eqMid,
            eqHigh: channels[index].eqHigh,
            activeSnippetId: channels[index].activeSnippetId
        )

        applySoloState()
    }

    private func applySoloState() {
        let hasSolo = channels.contains { $0.isSolo }

        for (index, channel) in channels.enumerated() {
            let orbit = "d\(channel.id)"
            if hasSolo && !channel.isSolo {
                engineManager.sendToTidal("\(orbit) $ silence")
            } else if !channel.isMuted {
                if let snippet = activePatterns[orbit] {
                    let effectiveGain = channel.volume * masterVolume
                    engineManager.sendToTidal(snippet.codeWithGain(effectiveGain))
                }
            }
        }
    }

    private func resendPatternForChannel(_ channelId: Int) {
        let orbit = "d\(channelId)"
        guard let snippet = activePatterns[orbit] else { return }

        let index = channelId - 1
        guard index >= 0 && index < channels.count else { return }

        let channel = channels[index]
        if !channel.isMuted {
            let effectiveGain = channel.volume * masterVolume
            engineManager.sendToTidal(snippet.codeWithGain(effectiveGain))
        }
    }

    // MARK: - Control

    func panic() {
        engineManager.panic()
        activePatterns.removeAll()

        for (index, channel) in channels.enumerated() {
            channels[index] = Channel(
                id: channel.id,
                volume: channel.volume,
                isMuted: channel.isMuted,
                isSolo: channel.isSolo,
                eqLow: channel.eqLow,
                eqMid: channel.eqMid,
                eqHigh: channel.eqHigh,
                activeSnippetId: nil
            )
        }
    }

    func toggleOrbit(_ orbitNumber: Int) {
        let orbit = "d\(orbitNumber)"
        if activePatterns[orbit] != nil {
            silenceOrbit(orbit)
        }
    }

    // MARK: - Helpers

    private func extractChannelIndex(from orbit: String) -> Int? {
        guard orbit.hasPrefix("d"),
              let number = Int(orbit.dropFirst()) else { return nil }
        return number - 1
    }

    private func appendAppLog(_ message: String, level: LogLevel = .info) {
        let entry = LogEntry(source: .app, level: level, message: message)
        logEntries.append(entry)
        if logEntries.count > 1000 {
            logEntries.removeFirst(logEntries.count - 1000)
        }
    }

    func clearLogs() {
        logEntries.removeAll()
        engineManager.clearLogs()
    }
}

