            let calculatedBpm = 60.0 / avgInterval

            if calculatedBpm >= 40 && calculatedBpm <= 300 {
                bpm = round(calculatedBpm * 10) / 10
            }
        }
    }

    // MARK: - Mixer

    func updateChannelVolume(_ channelId: Int, volume: Double) {
        guard channelId >= 1 && channelId <= channels.count else { return }
        let index = channelId - 1

        channels[index] = Channel(
            id: channels[index].id,
            volume: volume,
            isMuted: channels[index].isMuted,
            isSolo: channels[index].isSolo,
            eqLow: channels[index].eqLow,
            eqMid: channels[index].eqMid,
            eqHigh: channels[index].eqHigh,
            activeSnippetId: channels[index].activeSnippetId
        )

        resendPatternForChannel(channelId)
    }

    func toggleMute(_ channelId: Int) {
        guard channelId >= 1 && channelId <= channels.count else { return }
        let index = channelId - 1
        let newMuted = !channels[index].isMuted

        channels[index] = Channel(
            id: channels[index].id,
            volume: channels[index].volume,
            isMuted: newMuted,
            isSolo: channels[index].isSolo,
            eqLow: channels[index].eqLow,
            eqMid: channels[index].eqMid,
            eqHigh: channels[index].eqHigh,
            activeSnippetId: channels[index].activeSnippetId
        )

        if newMuted {
            engineManager.sendToTidal("d\(channelId) $ silence")
        } else {
            resendPatternForChannel(channelId)
        }
    }

    func toggleSolo(_ channelId: Int) {
        guard channelId >= 1 && channelId <= channels.count else { return }
        let index = channelId - 1
        let newSolo = !channels[index].isSolo

        channels[index] = Channel(
            id: channels[index].id,
            volume: channels[index].volume,
            isMuted: channels[index].isMuted,
            isSolo: newSolo,
            eqLow: channels[index].eqLow,
            eqMid: channels[index].eqMid,
            eqHigh: channels[index].eqHigh,
            activeSnippetId: channels[index].activeSnippetId
        )

        applySoloState()
    }

    private func applySoloState() {
        let hasSolo = channels.contains { $0.isSolo }

        for (index, channel) in channels.enumerated() {
            let orbit = "d\(channel.id)"
            if hasSolo && !channel.isSolo {
                engineManager.sendToTidal("\(orbit) $ silence")
            } else if !channel.isMuted {
                if let snippet = activePatterns[orbit] {
                    let effectiveGain = channel.volume * masterVolume
                    engineManager.sendToTidal(snippet.codeWithGain(effectiveGain))
                }
            }
        }
    }

    private func resendPatternForChannel(_ channelId: Int) {
        let orbit = "d\(channelId)"
        guard let snippet = activePatterns[orbit] else { return }

        let index = channelId - 1
        guard index >= 0 && index < channels.count else { return }

        let channel = channels[index]
        if !channel.isMuted {
            let effectiveGain = channel.volume * masterVolume
            engineManager.sendToTidal(snippet.codeWithGain(effectiveGain))
        }
    }

    // MARK: - Control

    func panic() {
        engineManager.panic()
        activePatterns.removeAll()

        for (index, channel) in channels.enumerated() {
            channels[index] = Channel(
                id: channel.id,
                volume: channel.volume,
                isMuted: channel.isMuted,
                isSolo: channel.isSolo,
                eqLow: channel.eqLow,
                eqMid: channel.eqMid,
                eqHigh: channel.eqHigh,
                activeSnippetId: nil
            )
        }
    }

    func toggleOrbit(_ orbitNumber: Int) {
        let orbit = "d\(orbitNumber)"
        if activePatterns[orbit] != nil {
            silenceOrbit(orbit)
        }
    }

    // MARK: - Helpers

    private func extractChannelIndex(from orbit: String) -> Int? {
        guard orbit.hasPrefix("d"),
              let number = Int(orbit.dropFirst()) else { return nil }
        return number - 1
    }

    private func appendAppLog(_ message: String, level: LogLevel = .info) {
        let entry = LogEntry(source: .app, level: level, message: message)
        logEntries.append(entry)
        if logEntries.count > 1000 {
            logEntries.removeFirst(logEntries.count - 1000)
        }
    }

    func clearLogs() {
        logEntries.removeAll()
        engineManager.clearLogs()
    }
}

