                Text(snippet.name)
                    .font(.system(size: Theme.fontSizePad, weight: .medium, design: .monospaced))
                    .lineLimit(2)
                    .multilineTextAlignment(.center)
                    .foregroundStyle(isActive ? Theme.textPrimary : Theme.textSecondary)

                Text(snippet.orbit)
                    .font(.caption2)
                    .foregroundStyle(Theme.textMuted)
            }
            .frame(width: Theme.padWidth, height: Theme.padHeight)
            .background(
                RoundedRectangle(cornerRadius: Theme.padCornerRadius)
                    .fill(isActive
                        ? snippet.accentColor.opacity(0.6)
                        : snippet.accentColor.opacity(0.15))
            )
            .overlay(
                RoundedRectangle(cornerRadius: Theme.padCornerRadius)
                    .stroke(snippet.accentColor.opacity(isActive ? 0.8 : 0.3), lineWidth: 1)
            )
            .shadow(color: isActive ? snippet.accentColor.opacity(0.6) : .clear, radius: isActive ? 12 : 0)
            .scaleEffect(isActive ? 1.02 : 1.0)
            .animation(.easeOut(duration: 0.1), value: isActive)
        }
        .buttonStyle(.plain)
        .contextMenu {
            Button("Edit Snippet...") { }
            Button("Clear Pad") { }
        }
