                                        .foregroundStyle(Theme.textSecondary)
                                }
                                Text(snippet.code)
                                    .font(.system(size: Theme.fontSizeCode, design: .monospaced))
                                    .foregroundStyle(Color.green)
                                    .textSelection(.enabled)
                            }
                        }
                    }

                    if appState.activePatterns.isEmpty {
                        Text("No active patterns")
                            .font(.system(size: Theme.fontSizeCode, design: .monospaced))
                            .foregroundStyle(Theme.textMuted)
                    }
                }
                .frame(maxWidth: .infinity, alignment: .leading)
            }
        }
        .padding()
        .background(Color.black.opacity(0.3))
    }
}

struct ConsoleLogView: View {
    @Environment(AppState.self) private var appState

    var body: some View {
        VStack(alignment: .leading, spacing: 8) {
            HStack {
                Text("CONSOLE")
                    .font(.system(size: Theme.fontSizeSection, weight: .semibold))
                    .foregroundStyle(Theme.textSecondary)

                Spacer()

                Button {
                    appState.clearLogs()
                } label: {
                    Image(systemName: "trash")
                        .font(.system(size: 10))
                }
                .buttonStyle(.plain)
                .foregroundStyle(Theme.textMuted)
            }

            ScrollViewReader { proxy in
                ScrollView {
                    LazyVStack(alignment: .leading, spacing: 2) {
                        ForEach(appState.logEntries) { entry in
