struct PadSectionView: View {
    @Environment(AppState.self) private var appState
    let category: SnippetCategory

    private let columns = Array(repeating: GridItem(.fixed(Theme.padWidth), spacing: Theme.padSpacing), count: 4)

    var body: some View {
        VStack(alignment: .leading, spacing: 8) {
            Text(category.displayName)
                .font(.system(size: Theme.fontSizeSection, weight: .semibold))
                .foregroundStyle(category.accentColor)

            LazyVGrid(columns: columns, spacing: Theme.padSpacing) {
                let categorySnippets = appState.snippets(for: category)
                ForEach(0..<category.padCount, id: \.self) { index in
                    if index < categorySnippets.count {
                        let snippet = categorySnippets[index]
                        PadButton(
                            snippet: snippet,
                            isActive: appState.isActive(snippet: snippet)
                        ) {
                            appState.togglePad(snippet: snippet)
                        }
                    } else {
                        emptyPad(category: category)
                    }
                }
            }
        }
        .padding()
        .cardStyle()
    }

    private func emptyPad(category: SnippetCategory) -> some View {
        RoundedRectangle(cornerRadius: Theme.padCornerRadius)
            .fill(category.accentColor.opacity(0.05))
            .frame(width: Theme.padWidth, height: Theme.padHeight)
            .overlay(
                RoundedRectangle(cornerRadius: Theme.padCornerRadius)
                    .stroke(category.accentColor.opacity(0.2), lineWidth: 1)
            )
    }
}

