struct VerticalSlider: View {
    @Binding var value: Double
    var range: ClosedRange<Double> = 0...1

    var body: some View {
        GeometryReader { geometry in
            let height = geometry.size.height
            let handleHeight: CGFloat = 16
            let trackWidth: CGFloat = 4
            let handleY = height - (CGFloat(value - range.lowerBound) / CGFloat(range.upperBound - range.lowerBound)) * (height - handleHeight) - handleHeight / 2

            ZStack {
                RoundedRectangle(cornerRadius: 2)
                    .fill(Theme.border)
                    .frame(width: trackWidth)

                RoundedRectangle(cornerRadius: 4)
                    .fill(Theme.textPrimary)
                    .frame(width: 12, height: handleHeight)
                    .position(x: geometry.size.width / 2, y: handleY)
                    .gesture(
                        DragGesture()
                            .onChanged { gesture in
                                let newY = gesture.location.y
                                let normalizedValue = 1 - (newY - handleHeight / 2) / (height - handleHeight)
                                let clampedValue = max(0, min(1, normalizedValue))
                                value = range.lowerBound + clampedValue * (range.upperBound - range.lowerBound)
                            }
                    )
            }
        }
    }
}

