import SwiftUI

struct EngineControlView: View {
    @Environment(AppState.self) private var appState

    @State private var isStartingSC = false
    @State private var isStartingTidal = false
    @State private var errorMessage: String?
    @State private var showError = false

    var body: some View {
        VStack(spacing: 12) {
            Text("ENGINE CONTROL")
                .font(.system(size: Theme.fontSizeSection, weight: .semibold))
                .foregroundStyle(Theme.textSecondary)

            superColliderSection

            tidalSection

            controlButtons
        }
        .padding()
        .cardStyle()
        .alert("Engine Error", isPresented: $showError) {
            Button("OK", role: .cancel) { }
        } message: {
            Text(errorMessage ?? "Unknown error")
        }
    }

    // MARK: - SuperCollider Section

    private var superColliderSection: some View {
        VStack(spacing: 8) {
            HStack {
                StatusIndicator(status: appState.engineManager.scStatus)

                Text("SuperCollider")
                    .font(.system(size: 12, weight: .medium))
                    .foregroundStyle(Theme.textPrimary)

                Spacer()

                Text(appState.engineManager.scStatus.displayName)
                    .font(.system(size: 10))
                    .foregroundStyle(Theme.textMuted)
            }

            Button {
                toggleSuperCollider()
            } label: {
                HStack(spacing: 6) {
                    if isStartingSC {
                        ProgressView()
                            .scaleEffect(0.6)
                            .frame(width: 14, height: 14)
                    } else {
                        Image(systemName: appState.engineManager.scStatus == .running ? "stop.fill" : "play.fill")
                            .font(.system(size: 10))
                    }

                    Text(appState.engineManager.scStatus == .running ? "Stop" : "Start")
                        .font(.system(size: 11, weight: .medium))
                }
                .frame(maxWidth: .infinity)
                .padding(.vertical, 6)
            }
            .buttonStyle(.bordered)
            .tint(appState.engineManager.scStatus == .running ? Theme.statusStopped : Theme.statusRunning)
            .disabled(isStartingSC || appState.engineManager.scStatus == .starting)
        }
        .padding(10)
        .background(Theme.surface.opacity(0.5))
        .clipShape(RoundedRectangle(cornerRadius: 6))
    }

    // MARK: - Tidal Section

    private var tidalSection: some View {
        VStack(spacing: 8) {
            HStack {
                StatusIndicator(status: appState.engineManager.tidalStatus)

                Text("Tidal Cycles")
                    .font(.system(size: 12, weight: .medium))
                    .foregroundStyle(Theme.textPrimary)

                Spacer()

                Text(appState.engineManager.tidalStatus.displayName)
                    .font(.system(size: 10))
                    .foregroundStyle(Theme.textMuted)
            }

            Button {
                toggleTidal()
            } label: {
                HStack(spacing: 6) {
                    if isStartingTidal {
                        ProgressView()
                            .scaleEffect(0.6)
                            .frame(width: 14, height: 14)
                    } else {
                        Image(systemName: appState.engineManager.tidalStatus == .running ? "stop.fill" : "play.fill")
                            .font(.system(size: 10))
                    }

                    Text(appState.engineManager.tidalStatus == .running ? "Stop" : "Start")
                        .font(.system(size: 11, weight: .medium))
                }
                .frame(maxWidth: .infinity)
                .padding(.vertical, 6)
            }
            .buttonStyle(.bordered)
            .tint(appState.engineManager.tidalStatus == .running ? Theme.statusStopped : Theme.statusRunning)
            .disabled(isStartingTidal || appState.engineManager.tidalStatus == .starting || appState.engineManager.scStatus != .running)
        }
        .padding(10)
        .background(Theme.surface.opacity(0.5))
        .clipShape(RoundedRectangle(cornerRadius: 6))
    }

    // MARK: - Control Buttons

    private var controlButtons: some View {
        HStack(spacing: 8) {
            Button {
                appState.panic()
            } label: {
                HStack(spacing: 4) {
                    Image(systemName: "exclamationmark.octagon.fill")
                        .font(.system(size: 10))
                    Text("PANIC")
                        .font(.system(size: 10, weight: .bold))
                }
                .frame(maxWidth: .infinity)
                .padding(.vertical, 8)
            }
            .buttonStyle(.bordered)
            .tint(Theme.statusStopped)
            .keyboardShortcut(.escape, modifiers: [])
            .disabled(appState.engineManager.tidalStatus != .running)

            Button {
                stopAll()
            } label: {
                HStack(spacing: 4) {
                    Image(systemName: "stop.circle.fill")
                        .font(.system(size: 10))
                    Text("STOP ALL")
                        .font(.system(size: 10, weight: .bold))
                }
                .frame(maxWidth: .infinity)
                .padding(.vertical, 8)
            }
            .buttonStyle(.bordered)
            .tint(Theme.statusStarting)
            .disabled(appState.engineManager.scStatus == .stopped && appState.engineManager.tidalStatus == .stopped)
        }
    }

    // MARK: - Actions

    private func toggleSuperCollider() {
        if appState.engineManager.scStatus == .running {
            if appState.engineManager.tidalStatus == .running {
                appState.engineManager.stopTidal()
            }
            appState.engineManager.stopSuperCollider()
        } else {
            isStartingSC = true
            Task {
                do {
                    try await appState.engineManager.startSuperCollider()
                } catch {
                    errorMessage = error.localizedDescription
                    showError = true
                }
                isStartingSC = false
            }
        }
    }

    private func toggleTidal() {
        if appState.engineManager.tidalStatus == .running {
            appState.engineManager.stopTidal()
        } else {
            isStartingTidal = true
            Task {
                do {
                    try await appState.engineManager.startTidal()
                } catch {
                    errorMessage = error.localizedDescription
                    showError = true
                }
                isStartingTidal = false
            }
        }
    }

    private func stopAll() {
        appState.engineManager.stopAll()
    }
}

