            appState.engineManager.stopTidal()
        } else {
            isStartingTidal = true
            Task {
                do {
                    try await appState.engineManager.startTidal()
                } catch {
                    errorMessage = error.localizedDescription
                    showError = true
                }
                isStartingTidal = false
            }
        }
    }

    private func stopAll() {
        appState.engineManager.stopAll()
    }
}

