import SwiftUI

@main
struct TidalPadControllerApp: App {
    @State private var appState = AppState()

    var body: some Scene {
        WindowGroup {
            ContentView()
                .environment(appState)
        }
        .windowStyle(.hiddenTitleBar)
        .defaultSize(width: 1440, height: 900)
        .commands {
            transportCommands
            padCommands
        }

        Settings {
            SettingsView()
        }
    }

    // MARK: - Commands

    @CommandsBuilder
    private var transportCommands: some Commands {
        CommandMenu("Transport") {
            Button("Panic (hush)") {
                appState.panic()
            }
            .keyboardShortcut(.escape, modifiers: [])

            Divider()

            Button("BPM +1") {
                appState.bpm = min(300, appState.bpm + 1)
            }
            .keyboardShortcut(.upArrow, modifiers: [.command])

            Button("BPM -1") {
                appState.bpm = max(40, appState.bpm - 1)
            }
            .keyboardShortcut(.downArrow, modifiers: [.command])

            Button("Tap Tempo") {
                appState.tapTempo()
            }
            .keyboardShortcut("t", modifiers: [])
        }
    }

    @CommandsBuilder
    private var padCommands: some Commands {
        CommandMenu("Pads") {
            ForEach(1...8, id: \.self) { n in
                Button("Toggle d\(n)") {
                    appState.toggleOrbit(n)
                }
                .keyboardShortcut(KeyEquivalent(Character("\(n)")), modifiers: [])
            }
        }
    }
}

// MARK: - Settings View

struct SettingsView: View {
    @AppStorage("sclangPath") private var sclangPath = "/Applications/SuperCollider.app/Contents/MacOS/sclang"
    @AppStorage("ghciPath") private var ghciPath = "/usr/local/bin/ghci"
    @AppStorage("tidalBootPath") private var tidalBootPath = "~/.cabal/share/BootTidal.hs"
    @AppStorage("oscPort") private var oscPort = 57120

    var body: some View {
        Form {
            Section("SuperCollider") {
                HStack {
                    TextField("sclang Path", text: $sclangPath)
                        .textFieldStyle(.roundedBorder)

                    Button("Browse...") {
                        browseForFile(title: "Select sclang") { url in
                            sclangPath = url.path
                        }
                    }
                }
            }

            Section("Tidal Cycles") {
                HStack {
                    TextField("GHCi Path", text: $ghciPath)
                        .textFieldStyle(.roundedBorder)

                    Button("Browse...") {
                        browseForFile(title: "Select ghci") { url in
                            ghciPath = url.path
                        }
                    }
                }

                HStack {
                    TextField("Boot File Path", text: $tidalBootPath)
                        .textFieldStyle(.roundedBorder)

                    Button("Browse...") {
                        browseForFile(title: "Select BootTidal.hs") { url in
                            tidalBootPath = url.path
                        }
                    }
                }
            }

            Section("OSC") {
                TextField("Port", value: $oscPort, format: .number)
                    .textFieldStyle(.roundedBorder)
                    .frame(width: 100)
            }
        }
        .formStyle(.grouped)
        .frame(width: 500, height: 300)
        .padding()
    }

    private func browseForFile(title: String, completion: @escaping (URL) -> Void) {
        let panel = NSOpenPanel()
        panel.title = title
        panel.canChooseFiles = true
        panel.canChooseDirectories = false
        panel.allowsMultipleSelection = false

        if panel.runModal() == .OK, let url = panel.url {
            completion(url)
        }
    }
}

