import Foundation

struct Snippet: Identifiable, Codable, Equatable, Sendable {
    let id: UUID
    var name: String
    var category: SnippetCategory
    var orbit: String
    var code: String
    var color: String
    var tags: [String]
    var gain: Double

    init(
        id: UUID = UUID(),
        name: String,
        category: SnippetCategory,
        orbit: String,
        code: String,
        color: String? = nil,
        tags: [String] = [],
        gain: Double = 0.8
    ) {
        self.id = id
        self.name = name
        self.category = category
        self.orbit = orbit
        self.code = code
        self.color = color ?? category.accentColor.toHex()
        self.tags = tags
        self.gain = gain
    }

    var accentColor: Color {
        Color(hex: color)
    }

    func codeWithGain(_ gainOverride: Double? = nil) -> String {
        let effectiveGain = gainOverride ?? gain
        let gainPattern = #"# gain \d+(\.\d+)?"#
        if code.range(of: gainPattern, options: .regularExpression) != nil {
            return code.replacingOccurrences(
                of: gainPattern,
                with: "# gain \(String(format: "%.2f", effectiveGain))",
                options: .regularExpression
            )
        } else {
            return "\(code) # gain \(String(format: "%.2f", effectiveGain))"
        }
    }
}

extension Snippet {
    static let placeholder = Snippet(
        name: "Empty",
        category: .rhythm,
        orbit: "d1",
        code: ""
    )

    static let sample = Snippet(
        name: "Four on the Floor",
        category: .rhythm,
        orbit: "d1",
        code: "d1 $ sound \"bd*4\"",
        tags: ["kick", "basic", "house"],
        gain: 0.9
    )
}

import SwiftUI

private extension Color {
    func toHex() -> String {
        guard let components = NSColor(self).cgColor.components else { return "#000000" }
        let r = Int(components[0] * 255)
        let g = Int(components[1] * 255)
        let b = Int(components[2] * 255)
        return String(format: "#%02X%02X%02X", r, g, b)
    }
}

