import Foundation
import Observation

enum EngineError: LocalizedError {
    case scNotReady
    case tidalNotReady
    case processNotFound(String)
    case bootFileNotFound(String)
    case startFailed(String)

    var errorDescription: String? {
        switch self {
        case .scNotReady:
            return "SuperCollider is not running"
        case .tidalNotReady:
            return "Tidal Cycles is not running"
        case .processNotFound(let path):
            return "Process not found at: \(path)"
        case .bootFileNotFound(let path):
            return "Boot file not found at: \(path)"
        case .startFailed(let reason):
            return "Failed to start: \(reason)"
        }
    }
}

@Observable
@MainActor
final class EngineManager {
    private(set) var scStatus: EngineStatus = .stopped
    private(set) var tidalStatus: EngineStatus = .stopped
    private(set) var logEntries: [LogEntry] = []

    var onLogEntry: ((LogEntry) -> Void)?

    private var scProcess: Process?
    private var tidalProcess: Process?
    private var tidalStdin: FileHandle?

    private let maxLogEntries = 1000

    // MARK: - Configuration

    var sclangPath: String {
        UserDefaults.standard.string(forKey: "sclangPath")
            ?? "/Applications/SuperCollider.app/Contents/MacOS/sclang"
    }

    var ghciPath: String {
        UserDefaults.standard.string(forKey: "ghciPath")
            ?? "/usr/local/bin/ghci"
    }

    var tidalBootPath: String {
        let defaultPath = "~/.cabal/share/BootTidal.hs"
        let path = UserDefaults.standard.string(forKey: "tidalBootPath") ?? defaultPath
        return NSString(string: path).expandingTildeInPath
    }

    // MARK: - SuperCollider

    func startSuperCollider() async throws {
        guard FileManager.default.fileExists(atPath: sclangPath) else {
            throw EngineError.processNotFound(sclangPath)
        }

        scStatus = .starting
        appendLog(.app, "Starting SuperCollider...")

        let process = Process()
        process.executableURL = URL(fileURLWithPath: sclangPath)

        let outputPipe = Pipe()
        process.standardOutput = outputPipe
        process.standardError = outputPipe

        let readHandle = outputPipe.fileHandleForReading
        readHandle.readabilityHandler = { [weak self] handle in
            let data = handle.availableData
            guard !data.isEmpty, let text = String(data: data, encoding: .utf8) else { return }

            Task { @MainActor [weak self] in
                guard let self = self else { return }

                for line in text.components(separatedBy: .newlines) where !line.isEmpty {
                    self.appendLog(.superCollider, line)

                    if line.contains("SuperDirt: listening") || line.contains("SuperCollider 3 server ready") {
                        self.scStatus = .running
                        self.appendLog(.app, "SuperCollider is ready")
                    }
                }
            }
        }

        process.terminationHandler = { [weak self] _ in
            Task { @MainActor [weak self] in
                self?.scStatus = .stopped
                self?.appendLog(.app, "SuperCollider terminated")
            }
        }

        do {
            try process.run()
            scProcess = process
            appendLog(.app, "SuperCollider process started (PID: \(process.processIdentifier))")

            try await Task.sleep(for: .seconds(2))
            sendToSC("SuperDirt.start;")
        } catch {
            scStatus = .error
            appendLog(.app, "Failed to start SuperCollider: \(error.localizedDescription)")
            throw EngineError.startFailed(error.localizedDescription)
        }
    }

    func stopSuperCollider() {
        appendLog(.app, "Stopping SuperCollider...")
        sendToSC("0.exit;")

        DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) { [weak self] in
            self?.scProcess?.terminate()
            self?.scProcess = nil
        }

        scStatus = .stopped
    }

    private func sendToSC(_ code: String) {
        guard let process = scProcess,
              let stdin = process.standardInput as? Pipe else { return }

        let data = "\(code)\n".data(using: .utf8)!
        try? stdin.fileHandleForWriting.write(contentsOf: data)
    }

    // MARK: - Tidal Cycles

    func startTidal() async throws {
        guard scStatus == .running else {
            throw EngineError.scNotReady
        }

        guard FileManager.default.fileExists(atPath: ghciPath) else {
            throw EngineError.processNotFound(ghciPath)
        }

        let expandedBootPath = tidalBootPath
        guard FileManager.default.fileExists(atPath: expandedBootPath) else {
            throw EngineError.bootFileNotFound(expandedBootPath)
        }

        tidalStatus = .starting
        appendLog(.app, "Starting Tidal Cycles...")

        let process = Process()
        process.executableURL = URL(fileURLWithPath: ghciPath)

        let inputPipe = Pipe()
        let outputPipe = Pipe()
        process.standardInput = inputPipe
        process.standardOutput = outputPipe
        process.standardError = outputPipe

        tidalStdin = inputPipe.fileHandleForWriting

        let readHandle = outputPipe.fileHandleForReading
        readHandle.readabilityHandler = { [weak self] handle in
            let data = handle.availableData
            guard !data.isEmpty, let text = String(data: data, encoding: .utf8) else { return }

            Task { @MainActor [weak self] in
                guard let self = self else { return }

                for line in text.components(separatedBy: .newlines) where !line.isEmpty {
                    self.appendLog(.tidal, line)

                    if line.contains("Listening for") || line.contains("tidal>") {
                        if self.tidalStatus == .starting {
                            self.tidalStatus = .running
                            self.appendLog(.app, "Tidal Cycles is ready")
                        }
                    }
                }
            }
        }

        process.terminationHandler = { [weak self] _ in
            Task { @MainActor [weak self] in
                self?.tidalStatus = .stopped
                self?.tidalStdin = nil
                self?.appendLog(.app, "Tidal Cycles terminated")
            }
        }

        do {
            try process.run()
            tidalProcess = process
            appendLog(.app, "Tidal process started (PID: \(process.processIdentifier))")

            try await Task.sleep(for: .milliseconds(500))
            sendToTidal(":script \(expandedBootPath)")
        } catch {
            tidalStatus = .error
            appendLog(.app, "Failed to start Tidal: \(error.localizedDescription)")
            throw EngineError.startFailed(error.localizedDescription)
        }
    }

    func stopTidal() {
        appendLog(.app, "Stopping Tidal Cycles...")
        sendToTidal("hush")

        DispatchQueue.main.asyncAfter(deadline: .now() + 0.3) { [weak self] in
            self?.tidalProcess?.terminate()
            self?.tidalProcess = nil
            self?.tidalStdin = nil
        }

        tidalStatus = .stopped
    }

    func sendToTidal(_ code: String) {
        guard let stdin = tidalStdin else {
            appendLog(.app, "Cannot send to Tidal: not running")
            return
        }

        let wrapped: String
        if code.contains("\n") || code.hasPrefix(":") {
            wrapped = "\(code)\n"
        } else {
            wrapped = ":{\n\(code)\n:}\n"
        }

        if let data = wrapped.data(using: .utf8) {
            do {
                try stdin.write(contentsOf: data)
            } catch {
                appendLog(.app, "Failed to send to Tidal: \(error.localizedDescription)")
            }
        }
    }

    // MARK: - Control

    func stopAll() {
        stopTidal()
        stopSuperCollider()
    }

    func panic() {
        appendLog(.app, "PANIC: Sending hush")
        sendToTidal("hush")
    }

    // MARK: - Logging

    private func appendLog(_ source: LogSource, _ message: String) {
        let level = LogEntry.detect(text: message, source: source)
        let entry = LogEntry(source: source, level: level, message: message)

        logEntries.append(entry)

        if logEntries.count > maxLogEntries {
            logEntries.removeFirst(logEntries.count - maxLogEntries)
        }

        onLogEntry?(entry)
    }

    func clearLogs() {
        logEntries.removeAll()
    }
}

