@Observable
@MainActor
final class EngineManager {
    private(set) var scStatus: EngineStatus = .stopped
    private(set) var tidalStatus: EngineStatus = .stopped
    private(set) var logEntries: [LogEntry] = []

    var onLogEntry: ((LogEntry) -> Void)?

    private var scProcess: Process?
    private var scStdin: FileHandle?
    private var tidalProcess: Process?
    private var tidalStdin: FileHandle?

    private let maxLogEntries = 1000

    // Continuation for async waiting
    private var superDirtReadyContinuation: CheckedContinuation<Void, Error>?
    private var tidalReadyContinuation: CheckedContinuation<Void, Error>?

    // MARK: - Configuration

    var sclangPath: String {
        UserDefaults.standard.string(forKey: "sclangPath")
            ?? "/Applications/SuperCollider.app/Contents/MacOS/sclang"
    }

    var ghciPath: String {
        UserDefaults.standard.string(forKey: "ghciPath")
            ?? "/usr/local/bin/ghci"
    }

    var tidalBootPath: String {
        let defaultPath = "~/.cabal/share/x86_64-osx-ghc-9.4.8/tidal-1.9.5/BootTidal.hs"
        let path = UserDefaults.standard.string(forKey: "tidalBootPath") ?? defaultPath
        return NSString(string: path).expandingTildeInPath
    }

    // MARK: - SuperDirt Startup Code

    private var superDirtStartupCode: String {
        """
        (
        s.options.numBuffers = 1024 * 256;
        s.options.memSize = 8192 * 32;
        s.options.numWireBufs = 128;
        s.options.maxNodes = 1024 * 32;
        s.options.numOutputBusChannels = 2;
        s.options.numInputBusChannels = 2;
        s.waitForBoot {
            ~dirt = SuperDirt(2, s);
            ~dirt.loadSoundFiles;
            s.sync;
            ~dirt.start(57120, [0, 0]);
            "*** SuperDirt is ready! ***".postln;
        };
        )
        """
    }

    // MARK: - SuperCollider

    func startSuperCollider() async throws {
        guard FileManager.default.fileExists(atPath: sclangPath) else {
            throw EngineError.processNotFound(sclangPath)
        }

        scStatus = .starting
        appendLog(.app, "Starting SuperCollider...")

        let process = Process()
        process.executableURL = URL(fileURLWithPath: sclangPath)

        let inputPipe = Pipe()
        let outputPipe = Pipe()
        process.standardInput = inputPipe
        process.standardOutput = outputPipe
        process.standardError = outputPipe

        scStdin = inputPipe.fileHandleForWriting

        let readHandle = outputPipe.fileHandleForReading
        readHandle.readabilityHandler = { [weak self] handle in
            let data = handle.availableData
            guard !data.isEmpty, let text = String(data: data, encoding: .utf8) else { return }

            Task { @MainActor [weak self] in
                guard let self = self else { return }

                for line in text.components(separatedBy: .newlines) where !line.isEmpty {
                    self.appendLog(.superCollider, line)

                    // SuperDirt ready detection
                    if line.contains("SuperDirt is ready") || line.contains("SuperDirt: listening") {
                        self.scStatus = .running
                        self.appendLog(.app, "✓ SuperDirt is ready!")
                        self.superDirtReadyContinuation?.resume()
                        self.superDirtReadyContinuation = nil
                    }

                    // Error detection
                    if line.contains("ERROR") || line.contains("Exception") {
                        if self.scStatus == .starting {
                            self.scStatus = .error
                            self.superDirtReadyContinuation?.resume(throwing: EngineError.startFailed(line))
                            self.superDirtReadyContinuation = nil
                        }
                    }
                }
            }
        }

        process.terminationHandler = { [weak self] proc in
            Task { @MainActor [weak self] in
                self?.scStatus = .stopped
                self?.scStdin = nil
                self?.appendLog(.app, "SuperCollider terminated (exit code: \(proc.terminationStatus))")
                self?.superDirtReadyContinuation?.resume(throwing: EngineError.startFailed("Process terminated"))
                self?.superDirtReadyContinuation = nil
            }
        }

        do {
            try process.run()
            scProcess = process
            appendLog(.app, "SuperCollider process started (PID: \(process.processIdentifier))")

            // Wait for sclang to initialize
            try await Task.sleep(for: .seconds(1))
            appendLog(.app, "Sending SuperDirt startup code...")

            // Send SuperDirt startup code
            sendToSC(superDirtStartupCode)

            // Wait for SuperDirt to be ready with timeout
            try await withThrowingTaskGroup(of: Void.self) { group in
                group.addTask { @MainActor in
                    try await withCheckedThrowingContinuation { [weak self] continuation in
                        self?.superDirtReadyContinuation = continuation
                    }
                }

                group.addTask {
                    try await Task.sleep(for: .seconds(60))
                    throw EngineError.timeout("SuperDirt did not start within 60 seconds")
                }

                // Wait for first to complete
                try await group.next()
                group.cancelAll()
            }

        } catch {
            if scStatus != .running {
                scStatus = .error
                appendLog(.app, "Failed to start SuperCollider: \(error.localizedDescription)")
            }
            throw error
        }
    }

    func stopSuperCollider() {
        appendLog(.app, "Stopping SuperCollider...")

        // Send quit command
        sendToSC("Server.killAll;")
        sendToSC("0.exit;")

        Task {
            try? await Task.sleep(for: .milliseconds(500))
            await MainActor.run {
                self.scProcess?.terminate()
                self.scProcess = nil
                self.scStdin = nil
                self.scStatus = .stopped
            }
        }
    }

    private func sendToSC(_ code: String) {
        guard let stdin = scStdin else {
            appendLog(.app, "Cannot send to SC: stdin not available")
            return
        }

        let codeWithNewline = code.hasSuffix("\n") ? code : "\(code)\n"
        if let data = codeWithNewline.data(using: .utf8) {
            do {
                try stdin.write(contentsOf: data)
            } catch {
                appendLog(.app, "Failed to send to SC: \(error.localizedDescription)")
            }
        }
    }

    // MARK: - Tidal Cycles

    func startTidal() async throws {
        guard scStatus == .running else {
            throw EngineError.scNotReady
        }

        guard FileManager.default.fileExists(atPath: ghciPath) else {
            throw EngineError.processNotFound(ghciPath)
        }

        // Try to find BootTidal.hs
        let bootPath = findBootTidalPath()
        guard let validBootPath = bootPath else {
            throw EngineError.bootFileNotFound(tidalBootPath)
        }

        tidalStatus = .starting
        appendLog(.app, "Starting Tidal Cycles...")
        appendLog(.app, "Using boot file: \(validBootPath)")

        let process = Process()
        process.executableURL = URL(fileURLWithPath: ghciPath)

        let inputPipe = Pipe()
        let outputPipe = Pipe()
        process.standardInput = inputPipe
        process.standardOutput = outputPipe
        process.standardError = outputPipe

        tidalStdin = inputPipe.fileHandleForWriting

        let readHandle = outputPipe.fileHandleForReading
        readHandle.readabilityHandler = { [weak self] handle in
            let data = handle.availableData
            guard !data.isEmpty, let text = String(data: data, encoding: .utf8) else { return }

            Task { @MainActor [weak self] in
                guard let self = self else { return }

                for line in text.components(separatedBy: .newlines) where !line.isEmpty {
                    self.appendLog(.tidal, line)

                    // Tidal ready detection
                    if line.contains("Listening for external controls") ||
                       line.contains("tidal>") ||
                       line.contains("Prelude Sound.Tidal.Context") {
                        if self.tidalStatus == .starting {
                            self.tidalStatus = .running
                            self.appendLog(.app, "✓ Tidal Cycles is ready!")
                            self.tidalReadyContinuation?.resume()
                            self.tidalReadyContinuation = nil
                        }
                    }

                    // Error detection
                    if line.contains("error:") || line.contains("Exception:") {
                        if self.tidalStatus == .starting {
                            self.tidalStatus = .error
                            self.tidalReadyContinuation?.resume(throwing: EngineError.startFailed(line))
                            self.tidalReadyContinuation = nil
                        }
                    }
                }
            }
        }

        process.terminationHandler = { [weak self] proc in
            Task { @MainActor [weak self] in
                self?.tidalStatus = .stopped
                self?.tidalStdin = nil
                self?.appendLog(.app, "Tidal Cycles terminated (exit code: \(proc.terminationStatus))")
                self?.tidalReadyContinuation?.resume(throwing: EngineError.startFailed("Process terminated"))
                self?.tidalReadyContinuation = nil
            }
        }

        do {
            try process.run()
            tidalProcess = process
            appendLog(.app, "GHCi process started (PID: \(process.processIdentifier))")

            // Wait for GHCi to initialize
            try await Task.sleep(for: .milliseconds(500))

            // Load BootTidal.hs
            appendLog(.app, "Loading Tidal boot script...")
            sendToTidalRaw(":script \(validBootPath)\n")

            // Wait for Tidal to be ready with timeout
            try await withThrowingTaskGroup(of: Void.self) { group in
                group.addTask { @MainActor in
                    try await withCheckedThrowingContinuation { [weak self] continuation in
                        self?.tidalReadyContinuation = continuation
                    }
                }

                group.addTask {
                    try await Task.sleep(for: .seconds(30))
                    throw EngineError.timeout("Tidal did not start within 30 seconds")
                }

                try await group.next()
                group.cancelAll()
            }

        } catch {
            if tidalStatus != .running {
                tidalStatus = .error
                appendLog(.app, "Failed to start Tidal: \(error.localizedDescription)")
            }
            throw error
        }
    }

    private func findBootTidalPath() -> String? {
        let possiblePaths = [
            tidalBootPath,
            NSString(string: "~/.cabal/share/x86_64-osx-ghc-9.4.8/tidal-1.9.5/BootTidal.hs").expandingTildeInPath,
            NSString(string: "~/.cabal/share/x86_64-osx-ghc-9.6.3/tidal-1.9.5/BootTidal.hs").expandingTildeInPath,
            NSString(string: "~/.cabal/share/arm64-osx-ghc-9.4.8/tidal-1.9.5/BootTidal.hs").expandingTildeInPath,
            NSString(string: "~/.cabal/share/arm64-osx-ghc-9.6.3/tidal-1.9.5/BootTidal.hs").expandingTildeInPath,
            NSString(string: "~/.ghcup/share/tidal/BootTidal.hs").expandingTildeInPath,
        ]

        for path in possiblePaths {
            if FileManager.default.fileExists(atPath: path) {
                return path
            }
        }

        // Search in .cabal directory
        let cabalSharePath = NSString(string: "~/.cabal/share").expandingTildeInPath
        if let contents = try? FileManager.default.contentsOfDirectory(atPath: cabalSharePath) {
            for dir in contents where dir.contains("ghc") {
                let tidalDir = "\(cabalSharePath)/\(dir)"
                if let tidalContents = try? FileManager.default.contentsOfDirectory(atPath: tidalDir) {
                    for subdir in tidalContents where subdir.starts(with: "tidal-") {
                        let bootPath = "\(tidalDir)/\(subdir)/BootTidal.hs"
                        if FileManager.default.fileExists(atPath: bootPath) {
                            return bootPath
                        }
                    }
                }
            }
        }

        return nil
    }

    func stopTidal() {
        appendLog(.app, "Stopping Tidal Cycles...")
        sendToTidal("hush")

        Task {
            try? await Task.sleep(for: .milliseconds(300))
            await MainActor.run {
                self.tidalProcess?.terminate()
                self.tidalProcess = nil
                self.tidalStdin = nil
                self.tidalStatus = .stopped
            }
        }
    }

    private func sendToTidalRaw(_ text: String) {
        guard let stdin = tidalStdin else {
            appendLog(.app, "Cannot send to Tidal: stdin not available")
            return
        }

        if let data = text.data(using: .utf8) {
            do {
                try stdin.write(contentsOf: data)
            } catch {
                appendLog(.app, "Failed to send to Tidal: \(error.localizedDescription)")
            }
        }
    }

    func sendToTidal(_ code: String) {
        guard let stdin = tidalStdin else {
            appendLog(.app, "Cannot send to Tidal: not running")
            return
        }

        // Multi-line code needs :{ ... :} wrapper
        let wrapped: String
        if code.contains("\n") {
            wrapped = ":{\n\(code)\n:}\n"
        } else if code.hasPrefix(":") {
            // GHCi commands like :script, :set
            wrapped = "\(code)\n"
        } else {
            // Single line Tidal code
            wrapped = ":{\n\(code)\n:}\n"
        }

        if let data = wrapped.data(using: .utf8) {
            do {
                try stdin.write(contentsOf: data)
            } catch {
                appendLog(.app, "Failed to send to Tidal: \(error.localizedDescription)")
            }
        }
    }

    // MARK: - Control

    func startAll() async throws {
        try await startSuperCollider()
        try await startTidal()
    }

    func stopAll() {
        stopTidal()

        Task {
            try? await Task.sleep(for: .milliseconds(500))
            await MainActor.run {
                self.stopSuperCollider()
            }
        }
    }

    func panic() {
        appendLog(.app, "PANIC: Sending hush")
        sendToTidal("hush")
    }

    // MARK: - Logging

    private func appendLog(_ source: LogSource, _ message: String) {
        let level = LogEntry.detect(text: message, source: source)
        let entry = LogEntry(source: source, level: level, message: message)

        logEntries.append(entry)

        if logEntries.count > maxLogEntries {
            logEntries.removeFirst(logEntries.count - maxLogEntries)
        }

        onLogEntry?(entry)
    }

    func clearLogs() {
        logEntries.removeAll()
    }
}

