import Foundation
import Observation

enum EngineError: LocalizedError {
    case scNotReady
    case tidalNotReady
    case processNotFound(String)
    case bootFileNotFound(String)
    case startFailed(String)
    case timeout(String)

    var errorDescription: String? {
        switch self {
        case .scNotReady:
            return "SuperCollider is not running"
        case .tidalNotReady:
            return "Tidal Cycles is not running"
        case .processNotFound(let path):
            return "Process not found at: \(path)"
        case .bootFileNotFound(let path):
            return "Boot file not found at: \(path)"
        case .startFailed(let reason):
            return "Failed to start: \(reason)"
        case .timeout(let message):
            return "Timeout: \(message)"
        }
    }
}

@Observable
@MainActor
final class EngineManager {
    private(set) var scStatus: EngineStatus = .stopped
    private(set) var tidalStatus: EngineStatus = .stopped
    private(set) var logEntries: [LogEntry] = []

    var onLogEntry: ((LogEntry) -> Void)?

    private var scProcess: Process?
    private var scStdin: FileHandle?
    private var tidalProcess: Process?
    private var tidalStdin: FileHandle?

    private let maxLogEntries = 1000

    // Continuation for async waiting
    private var superDirtReadyContinuation: CheckedContinuation<Void, Error>?
    private var tidalReadyContinuation: CheckedContinuation<Void, Error>?

    // MARK: - Configuration

    var sclangPath: String {
        UserDefaults.standard.string(forKey: "sclangPath")
            ?? "/Applications/SuperCollider.app/Contents/MacOS/sclang"
    }

    var ghciPath: String {
        if let saved = UserDefaults.standard.string(forKey: "ghciPath"),
           FileManager.default.fileExists(atPath: saved) {
            return saved
        }
        // Try common paths
        let possiblePaths = [
            NSString(string: "~/.ghcup/bin/ghci").expandingTildeInPath,
            "/usr/local/bin/ghci",
            "/opt/homebrew/bin/ghci",
        ]
        for path in possiblePaths {
            if FileManager.default.fileExists(atPath: path) {
                return path
            }
        }
        return NSString(string: "~/.ghcup/bin/ghci").expandingTildeInPath
    }

    var tidalBootPath: String {
        if let saved = UserDefaults.standard.string(forKey: "tidalBootPath") {
            let expanded = NSString(string: saved).expandingTildeInPath
            if FileManager.default.fileExists(atPath: expanded) {
                return expanded
            }
        }
        // Will be searched dynamically in findBootTidalPath()
        return ""
    }

    // MARK: - SuperDirt Startup Code

    private var superDirtStartupCode: String {
        """
        (
        s.options.numBuffers = 1024 * 256;
        s.options.memSize = 8192 * 32;
        s.options.numWireBufs = 128;
        s.options.maxNodes = 1024 * 32;
        s.options.numOutputBusChannels = 2;
        s.options.numInputBusChannels = 2;
        s.waitForBoot {
            ~dirt = SuperDirt(2, s);
            ~dirt.loadSoundFiles;
            s.sync;
            ~dirt.start(57120, [0, 0]);
            "*** SuperDirt is ready! ***".postln;
        };
        )
        """
    }

    // MARK: - SuperCollider

    func startSuperCollider() async throws {
        guard FileManager.default.fileExists(atPath: sclangPath) else {
            throw EngineError.processNotFound(sclangPath)
        }

        scStatus = .starting
        appendLog(.app, "Starting SuperCollider...")

        let process = Process()
        process.executableURL = URL(fileURLWithPath: sclangPath)

        let inputPipe = Pipe()
        let outputPipe = Pipe()
        process.standardInput = inputPipe
        process.standardOutput = outputPipe
        process.standardError = outputPipe

        scStdin = inputPipe.fileHandleForWriting

        let readHandle = outputPipe.fileHandleForReading
        readHandle.readabilityHandler = { [weak self] handle in
            let data = handle.availableData
            guard !data.isEmpty, let text = String(data: data, encoding: .utf8) else { return }

            Task { @MainActor [weak self] in
                guard let self = self else { return }

                for line in text.components(separatedBy: .newlines) where !line.isEmpty {
                    self.appendLog(.superCollider, line)

                    // SuperDirt ready detection
                    if line.contains("SuperDirt is ready") || line.contains("SuperDirt: listening") {
                        self.scStatus = .running
                        self.appendLog(.app, "✓ SuperDirt is ready!")
                        self.superDirtReadyContinuation?.resume()
                        self.superDirtReadyContinuation = nil
                    }

                    // Error detection
                    if line.contains("ERROR") || line.contains("Exception") {
                        if self.scStatus == .starting {
                            self.scStatus = .error
                            self.superDirtReadyContinuation?.resume(throwing: EngineError.startFailed(line))
                            self.superDirtReadyContinuation = nil
                        }
                    }
                }
            }
        }

        process.terminationHandler = { [weak self] proc in
            Task { @MainActor [weak self] in
                self?.scStatus = .stopped
                self?.scStdin = nil
                self?.appendLog(.app, "SuperCollider terminated (exit code: \(proc.terminationStatus))")
                self?.superDirtReadyContinuation?.resume(throwing: EngineError.startFailed("Process terminated"))
                self?.superDirtReadyContinuation = nil
            }
        }

        do {
            try process.run()
            scProcess = process
            appendLog(.app, "SuperCollider process started (PID: \(process.processIdentifier))")

            // Wait for sclang to initialize
            try await Task.sleep(for: .seconds(1))
            appendLog(.app, "Sending SuperDirt startup code...")

            // Send SuperDirt startup code
            sendToSC(superDirtStartupCode)

            // Wait for SuperDirt to be ready with timeout
            try await withThrowingTaskGroup(of: Void.self) { group in
                group.addTask { @MainActor in
                    try await withCheckedThrowingContinuation { [weak self] continuation in
                        self?.superDirtReadyContinuation = continuation
                    }
                }

                group.addTask {
                    try await Task.sleep(for: .seconds(60))
                    throw EngineError.timeout("SuperDirt did not start within 60 seconds")
                }

                // Wait for first to complete
                try await group.next()
                group.cancelAll()
            }

        } catch {
            if scStatus != .running {
                scStatus = .error
                appendLog(.app, "Failed to start SuperCollider: \(error.localizedDescription)")
            }
            throw error
        }
    }

    func stopSuperCollider() {
        appendLog(.app, "Stopping SuperCollider...")

        // Send quit command
        sendToSC("Server.killAll;")
        sendToSC("0.exit;")

        Task {
            try? await Task.sleep(for: .milliseconds(500))
            await MainActor.run {
                self.scProcess?.terminate()
                self.scProcess = nil
                self.scStdin = nil
                self.scStatus = .stopped
            }
        }
    }

    private func sendToSC(_ code: String) {
        guard let stdin = scStdin else {
            appendLog(.app, "Cannot send to SC: stdin not available")
            return
        }

        let codeWithNewline = code.hasSuffix("\n") ? code : "\(code)\n"
