func playSnippet(_ snippet: Snippet) {
    let orbit = snippet.orbit
    let channelIndex = extractChannelIndex(from: orbit)

    guard let index = channelIndex, index >= 0 && index < channels.count else {
        appendAppLog("Invalid orbit: \(orbit)", level: .error)
        return
    }

    let effectiveGain = channels[index].effectiveVolume * masterVolume
    let code = snippet.codeWithGain(effectiveGain)

    engineManager.sendToTidal(code)
    activePatterns[orbit] = snippet

    channels[index] = Channel(
        id: channels[index].id,
        volume: channels[index].volume,
        isMuted: channels[index].isMuted,
        isSolo: channels[index].isSolo,
        eqLow: channels[index].eqLow,
        eqMid: channels[index].eqMid,
        eqHigh: channels[index].eqHigh,
        activeSnippetId: snippet.id
    )

    appendAppLog("Playing \(snippet.name) on \(orbit)")
}

func silenceOrbit(_ orbit: String) {
    engineManager.sendToTidal("\(orbit) $ silence")
    activePatterns.removeValue(forKey: orbit)

    if let channelIndex = extractChannelIndex(from: orbit),
       channelIndex >= 0 && channelIndex < channels.count {
        channels[channelIndex] = Channel(
            id: channels[channelIndex].id,
            volume: channels[channelIndex].volume,
            isMuted: channels[channelIndex].isMuted,
            isSolo: channels[channelIndex].isSolo,
            eqLow: channels[channelIndex].eqLow,
            eqMid: channels[channelIndex].eqMid,
            eqHigh: channels[channelIndex].eqHigh,
            activeSnippetId: nil
        )
    }

    appendAppLog("Silenced \(orbit)")
}

